# Create an LLDB script file that doesn't use the -s flag but instead pipes commands
cat > /tmp/lldb_dismiss.txt << 'EOF'
process attach --name Element
expr import UIKit
expr let windows = UIApplication.shared.windows
expr windows.count
expr if let window = windows.first {
    var current: UIViewController? = window.rootViewController
    while let vc = current {
        print("VC: \(type(of: vc))")
        if vc is UIAlertController {
            print("Found UIAlertController!")
            (vc as? UIAlertController)?.dismiss(animated: false, completion: nil)
            break
        }
        if let navVC = vc as? UINavigationController {
            current = navVC.visibleViewController
        } else if let tabVC = vc as? UITabBarController {
            current = tabVC.selectedViewController
        } else {
            if let presented = vc.presentedViewController {
                print("Found presented VC: \(type(of: presented))")
                if presented is UIAlertController {
                    (presented as? UIAlertController)?.dismiss(animated: false, completion: nil)
                }
                current = presented
            } else {
                break
            }
        }
    }
}
quit
EOF

